const portraitKey = (value: string) => value.toLocaleLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "");
export function cardGamePortraitFor(sport: string, name: string): string | undefined { return cardGamePortraitsByName[`${sport}:${portraitKey(name)}`]; }
